ALTER TABLE public.linkedin_posts ADD COLUMN IF NOT EXISTS image_path text;
CREATE POLICY "linkedin images own read" ON storage.objects FOR SELECT TO authenticated USING (bucket_id='linkedin-images' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "linkedin images own insert" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id='linkedin-images' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "linkedin images own update" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id='linkedin-images' AND (storage.foldername(name))[1] = auth.uid()::text);